package com.zhiyu.modules.group.service;
import com.baomidou.mybatisplus.core.toolkit.IdWorker;
import com.zhiyu.common.exception.BusinessException;
import com.zhiyu.security.BusinessAccess;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service @RequiredArgsConstructor
public class GroupCompanionService {
    private final JdbcTemplate db;
    private final BusinessAccess access;
    private void member(long id,long uid,boolean lock){if(db.queryForList("SELECT id FROM support_group WHERE id=? AND status=1 AND deleted=0"+(lock?" FOR UPDATE":""),id).isEmpty())throw new BusinessException(1004,"小组未开放");if(db.queryForObject("SELECT COUNT(*) FROM group_member WHERE group_id=? AND user_id=? AND deleted=0",Integer.class,id,uid)==0)throw new BusinessException(1003,"仅小组成员可访问");}
    public List<Map<String,Object>> list(long id){long uid=access.user();member(id,uid,false);var rows=db.queryForList("SELECT c.id,c.state,c.requester_id,u.nickname FROM group_companion c JOIN user u ON u.id=CASE WHEN c.first_user_id=? THEN c.second_user_id ELSE c.first_user_id END AND u.deleted=0 AND u.status=1 WHERE c.group_id=? AND c.deleted=0 AND (c.first_user_id=? OR c.second_user_id=?) ORDER BY c.update_time DESC,c.id DESC LIMIT 100",uid,id,uid,uid);for(var r:rows){r.put("id",r.get("id").toString());r.put("incoming",((Number)r.remove("requester_id")).longValue()!=uid);}return rows;}
    @Transactional public void invite(long id,long memberId){long uid=access.consentedUser();member(id,uid,true);var rows=db.queryForList("SELECT m.user_id FROM group_member m JOIN user u ON u.id=m.user_id AND u.deleted=0 AND u.status=1 WHERE m.id=? AND m.group_id=? AND m.deleted=0",memberId,id);if(rows.isEmpty())throw new BusinessException(1004,"成员已离开");long target=((Number)rows.get(0).get("user_id")).longValue();if(target==uid)throw new BusinessException(1001,"请选择其他成员");long first=Math.min(uid,target),second=Math.max(uid,target);var existing=db.queryForList("SELECT * FROM group_companion WHERE group_id=? AND first_user_id=? AND second_user_id=?",id,first,second);if(!existing.isEmpty()&&List.of("PENDING","ACCEPTED").contains(existing.get(0).get("state")))throw new BusinessException(3001,"已有邀请或已结伴");if(existing.isEmpty())db.update("INSERT INTO group_companion(id,group_id,first_user_id,second_user_id,requester_id,state) VALUES(?,?,?,?,?,'PENDING')",IdWorker.getId(),id,first,second,uid);else db.update("UPDATE group_companion SET requester_id=?,state='PENDING',deleted=0,update_time=CURRENT_TIMESTAMP WHERE id=?",uid,existing.get(0).get("id"));}
    @Transactional public void respond(long id,long invitation,String action){long uid="ACCEPT".equals(action)?access.consentedUser():access.user();member(id,uid,true);var rows=db.queryForList("SELECT * FROM group_companion WHERE id=? AND group_id=? AND deleted=0 AND (first_user_id=? OR second_user_id=?)",invitation,id,uid,uid);if(rows.isEmpty())throw new BusinessException(1004,"邀请不存在");var r=rows.get(0);if(!List.of("ACCEPT","DECLINE","CANCEL").contains(action))throw new BusinessException(1001,"请选择有效操作");if(!"CANCEL".equals(action)&&(!"PENDING".equals(r.get("state"))||((Number)r.get("requester_id")).longValue()==uid))throw new BusinessException(3001,"只有收到邀请的成员可以回应待处理邀请");if("ACCEPT".equals(action)){long other=((Number)r.get("requester_id")).longValue();member(id,other,false);if(db.queryForObject("SELECT COUNT(*) FROM user WHERE id=? AND status=1 AND deleted=0",Integer.class,other)==0)throw new BusinessException(3001,"对方账号已不可用");}db.update("UPDATE group_companion SET state=?,update_time=CURRENT_TIMESTAMP WHERE id=?",switch(action){case "ACCEPT"->"ACCEPTED";case "DECLINE"->"DECLINED";default->"CANCELLED";},invitation);}
}
